from lib import *
S = SS('k29')
F1 = [['kubectl delete', ''], ['SIGTERM → PID 1', '没有处理函数'], ['等满宽限期', '3 秒 → 3.9 s,8 秒 → 8.8 s'], ['SIGKILL', 'Pod 消失']]
F2 = [['SIGTERM → PID 1', 'trap exit 0'], ['sh 处理信号', '1.2 s / 0.8 s'], ['Pod 消失', '不用等宽限期']]
F3 = [['--grace-period=2', '2.8 s'], ['--grace-period=0 --force', '0.1 s'], ['spec 里写 0', '0.1 s'], ['不写', '默认 30 → 30.3 s']]
F4 = [['sh -c "tail …; echo done"', '1 = sh,11 = tail'], ['SIGTERM → sh', '忽略,tail 没收到'], ['5.6 s', '等到 SIGKILL'], ['trap 转发', '0.5 s']]
PANELS = [('f', 'flow', 'SIGTERM 与 SIGKILL'), ('t', 'term', '实测输出'), ('b', 'bars', '删除耗时(秒)'), ('kv', 'kv', '要点')]
steps = [
    step("1 号进程不处理 SIGTERM:命令 sh -c \"sleep 3600\"(busybox 的 sleep 是 shell 内置,1 号进程就是 sh 本身),terminationGracePeriodSeconds=3 时 kubectl delete 到 Pod 消失 3.9 秒,=8 时 8.8 秒;命令改成 exec sleep 3600(sleep 自己是 1 号进程)同样是 3.8 秒。Linux 不会因为没有处理函数的 SIGTERM 终止 1 号进程,只能等 SIGKILL。", f=fl(F1, cur=[1], mark=[2], done=[3]), t=tl(S(1), mark=lidx(S(1), 'terminationGracePeriodSeconds=3', 'terminationGracePeriodSeconds=8', '同样的宽限期 3 秒')), b=bars([['宽限期 3 秒', 3.9, '3.9'], ['宽限期 8 秒', 8.8, '8.8'], ['exec sleep,宽限期 3 秒', 3.8, '3.8']], 8.8, mark=[0, 1, 2]), kv=KV([['1 号进程', '没有处理函数的信号会被内核忽略(SIGKILL 除外)'], ['不处理 SIGTERM', '要等满 terminationGracePeriodSeconds'], ['多出来的零点几秒', 'kubelet 与容器运行时的开销']], ['1 号进程'])),
    step("应用自己处理 SIGTERM:宽限期 30 秒,sh 里 trap exit 0 TERM、循环 sleep 1,删除用了 1.2 秒(shell 要等当前的 sleep 1 结束才处理信号);trap exit 0 TERM; sleep 3600 & wait(wait 会被信号立即打断)用了 0.8 秒。完全不用等宽限期。", f=fl(F2, cur=[1], done=[0, 2]), t=tl(S(2), mark=lidx(S(2), '1.2 秒', '0.8 秒')), b=bars([['trap + 循环 sleep 1', 1.2, '1.2'], ['trap + wait', 0.8, '0.8']], 1.2, done=[0, 1]), kv=KV([['有处理函数', '收到就退出,不等宽限期'], ['shell 的细节', '前台命令执行期间 trap 不会立刻跑'], ['wait', '会被信号打断']], ['有处理函数'])),
    step("宽限期可以覆盖:Pod 里写 terminationGracePeriodSeconds=60,kubectl delete --grace-period=2 用了 2.8 秒;--grace-period=0 --force 用了 0.1 秒(API 对象立即删除);spec.terminationGracePeriodSeconds=0 同样 0.1 秒;不写的话服务端补上默认值 30,删除一个不处理 SIGTERM 的 Pod 用了 30.3 秒。", f=fl(F3, cur=[0, 1, 2], mark=[3]), t=tl(S(3), mark=lidx(S(3), '默认值'), done=lidx(S(3), '--grace-period=2', '--grace-period=0', 'spec.terminationGracePeriodSeconds=0')), b=bars([['--grace-period=2', 2.8, '2.8'], ['--grace-period=0 --force', 0.1, '0.1'], ['spec 里写 0', 0.1, '0.1'], ['默认 30 秒', 30.3, '30.3']], 30.3, mark=[3], done=[0, 1, 2]), kv=KV([['默认', '30 秒'], ['kubectl --grace-period', '可以在删除时覆盖'], ['0 / --force', '立即删除 API 对象,容器随即被杀,没有优雅退出']], ['默认'])),
    step("sh -c 包一层的陷阱:sh -c \"tail -f /dev/null; echo done\":容器里 1 号是 sh、11 号是 tail;SIGTERM 发给 1 号 sh,sh 忽略,tail 根本没收到,宽限期 5 秒的 Pod 5.6 秒才消失;换成 tail 放后台、trap 'kill $c' TERM、wait $c 把信号转给子进程,只用了 0.5 秒。", f=fl(F4, cur=[1], mark=[2], done=[3]), t=tl(S(4), mark=lidx(S(4), '没有转发'), done=lidx(S(4), '转发:')), b=bars([['没有转发', 5.6, '5.6'], ['trap 转发', 0.5, '0.5']], 5.6, mark=[0], done=[1]), kv=KV([['1 号进程', '负责转发信号,否则子进程收不到'], ['做法', 'exec 替换 shell,或在 trap 里转发,或用 tini 之类的 init'], ['shareProcessNamespace', '也能让 Pod 里有一个真正的 init']], ['1 号进程'])),
]
A = mkartk('k29', 29, 'Kubernetes,terminationGracePeriodSeconds,SIGTERM,SIGKILL,优雅退出,1 号进程,真实验证,动画演示',
    '在 kind 集群里量出 SIGTERM 与 SIGKILL 之间发生了什么:1 号进程没有 SIGTERM 处理函数时 Pod 要等满宽限期(3 秒 → 3.9 秒、8 秒 → 8.8 秒、默认 30 秒 → 30.3 秒);有 trap 时 0.8~1.2 秒退出;kubectl delete --grace-period=2 覆盖为 2.8 秒,--grace-period=0 --force 与 spec 里写 0 都是 0.1 秒;sh -c 包一层时子进程收不到 SIGTERM 要等 5.6 秒,用 trap 转发只要 0.5 秒。',
    '为什么有的 Pod 删除要卡 30 秒?terminationGracePeriodSeconds 到底影响什么?这篇用同样的 busybox 容器,只改 1 号进程怎么对待 SIGTERM,把删除耗时一项项量出来,并验证 kubectl delete 的 --grace-period 覆盖和 sh -c 包一层的信号转发陷阱。',
    [('30.3 秒', '不写 terminationGracePeriodSeconds 时,删除一个不处理 SIGTERM 的 Pod 的耗时(默认值 30)'), ('0.8~1.2 秒', '应用自己 trap SIGTERM 后的删除耗时,与宽限期 30 秒无关'), ('5.6 秒 vs 0.5 秒', 'sh -c 包着 tail 时,没有转发与用 trap 转发信号的删除耗时(宽限期 5 秒)')],
    [('不处理 SIGTERM 就要等满', '<p>kubelet 先给 1 号进程发 SIGTERM,宽限期用完再 SIGKILL。命令是 <code>sh -c "sleep 3600"</code>(busybox 的 <code>sleep</code> 是 shell 内置,不 fork,1 号进程就是 <code>sh</code> 本身),<code>terminationGracePeriodSeconds: 3</code> 时删除用了 3.9 秒,设成 8 时用了 8.8 秒;改成 <code>exec sleep 3600</code>(<code>sleep</code> 自己是 1 号进程)同样等满。原因是 Linux 对 1 号进程特殊对待:没有处理函数的信号(SIGKILL 除外)会被忽略,所以进程不会因为 SIGTERM 退出。</p>'),
     ('处理了就很快', '<p>应用自己处理 SIGTERM:<code>trap exit 0 TERM</code> 加循环 <code>sleep 1</code>,删除用了 1.2 秒(shell 要等当前这次 <code>sleep 1</code> 结束才跑 trap);<code>trap … TERM; sleep 3600 &amp; wait</code> 里 <code>wait</code> 会被信号立即打断,0.8 秒。宽限期设成 30 秒也不会白等,宽限期只是上限。</p>'),
     ('覆盖与零', '<p>宽限期可以在删除时覆盖:Pod 里写的是 60 秒,<code>kubectl delete --grace-period=2</code> 用了 2.8 秒。<code>--grace-period=0 --force</code> 立即从 API 里删掉对象(0.1 秒),容器随后被直接杀掉;<code>spec.terminationGracePeriodSeconds: 0</code> 也是 0.1 秒。不写这个字段时服务端补上默认值 30,不处理 SIGTERM 的 Pod 删除就卡 30.3 秒。</p>'),
     ('sh -c 的陷阱', '<p><code>sh -c "tail -f /dev/null; echo done"</code>:容器里 1 号是 <code>sh</code>、11 号是 <code>tail</code>,SIGTERM 发给 1 号,<code>sh</code> 没有处理函数就忽略了,<code>tail</code> 根本没收到,5 秒宽限期的 Pod 5.6 秒才被 SIGKILL。把 <code>tail</code> 放到后台、<code>trap \'kill $c\' TERM</code> 再 <code>wait $c</code> 把信号转发给子进程,0.5 秒就退出。更常见的做法是用 <code>exec</code> 让真正的程序成为 1 号进程,或在镜像里放 tini 一类的 init。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);所有 Pod 用 busybox:1.36;删除耗时是 kubectl delete --wait=true 的整体耗时(含 kubectl 与 API 往返,约 0.1~0.5 秒的开销);容器里的进程列表用 kubectl exec 的 ps 读出;每种情形各一次',
     '没有验证:真正的应用(Java、Go 程序)的 SIGTERM 处理;shareProcessNamespace 下 pause 作为 1 号进程的效果;preStop 与宽限期的组合(上一篇);Pod 的 DeletionGracePeriod 在节点优雅关机时的缩短;kubectl delete --now;grace-period 为负数;SIGKILL 之后容器运行时清理失败时 Pod 的残留'],
    'SIGTERM 与 SIGKILL', PANELS)
